"""Distance Between Two Nodes in a BST — split point, then two descents.

Time: O(h)   Space: O(1)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def findDistanceBST(self, root, p: int, q: int) -> int:
        node = root
        while node:
            if p < node.val and q < node.val:
                node = node.left
            elif p > node.val and q > node.val:
                node = node.right
            else:
                break                       # node is the LCA

        def depth(start, value) -> int:
            steps = 0
            while start and start.val != value:
                start = start.left if value < start.val else start.right
                steps += 1
            return steps

        return depth(node, p) + depth(node, q)
